    // Check if the result map is empty
    if (resultMap.isEmpty()) {
        throw new IllegalArgumentException("Result map cannot be empty");
    }

    // Create a new bipartite graph
    Graph<V, E> bipartiteGraph = new Graph<V, E>();

    // Add vertices to the bipartite graph
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        bipartiteGraph.addVertex(entry.getValue());
    }

    // Add edges to the bipartite graph
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        V sourceVertex = entry.getValue();
        for (Map.Entry<String, V> neighborEntry : resultMap.entrySet()) {
            V neighborVertex = neighborEntry.getValue();
            if (!sourceVertex.equals(neighborVertex)) {
                bipartiteGraph.addEdge(sourceVertex, neighborVertex);
            }
        }
    }

    // Set the bipartite graph as the target graph
    target.setGraph(bipartiteGraph);
}

