public static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the graph is null or empty
    if (graph == null || graph.isEmpty()) {
        return false;
    }

    // Check if the vertices set is null or empty
    if (vertices == null || vertices.isEmpty()) {
        return false;
    }

    // Check if the graph contains all the vertices in the set
    if (!graph.containsAll(vertices)) {
        return false;
    }

    // Check if the graph is connected
    if (!isConnected(graph)) {
        return false;
    }

    // Check if the graph is a clique
    for (V vertex : vertices) {
        for (V otherVertex : vertices) {
            if (vertex != otherVertex && !graph.containsEdge(vertex, otherVertex)) {
                return false;
            }
        }
    }

    return true;
}

