public final MatchResult match(CharSequence uri) {
    if (uri == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }
    if (!uri.toString().startsWith(this.pattern)) {
        return null;
    }
    String[] pathSegments = uri.toString().substring(this.pattern.length()).split("/");
    Map<String, String> pathParameters = new HashMap<>();
    for (int i = 0; i < pathSegments.length; i++) {
        String pathSegment = pathSegments[i];
        if (pathSegment.startsWith("{") && pathSegment.endsWith("}")) {
            String parameterName = pathSegment.substring(1, pathSegment.length() - 1);
            pathParameters.put(parameterName, pathSegments[i + 1]);
        }
    }
    return new MatchResult(this.pattern, pathParameters);
}

