    int filenameStartIndex = path.lastIndexOf("/");
    if (filenameStartIndex == -1) {
        return path;
    }
    int extensionStartIndex = path.lastIndexOf(".");
    if (extensionStartIndex == -1 || extensionStartIndex < filenameStartIndex) {
        return path;
    }
    return path.substring(0, extensionStartIndex);
}

